def _v383_get(core, path):
    """le um valor do core por caminho (chaves de dict e indices de lista); ausencia => None, nunca levanta."""
    o = core
    try:
        for p in path:
            if isinstance(o, dict):
                o = o.get(p)
            elif isinstance(o, list) and isinstance(p, int) and p < len(o):
                o = o[p]
            else:
                return None
        return o
    except Exception:
        return None


def _v383_final_step_name_from_source(src):
    """le a string de finalStepNameProposed do fonte Lean embutido (sem executar nada); falha de leitura => ''."""
    try:
        m = re.search(r'def finalStepNameProposed : String :=\s*"([^"]+)"', src)
        return m.group(1) if m else ""
    except Exception:
        return ""


def _v383_read_prereg():
    """le o pre-registro V1.4 (JSON + MD) por bytes e devolve (dados, sha256 lidos, erro); nunca levanta."""
    out = {"json": None, "md": None, "sha256": {}, "erro": None}
    try:
        for k in ("json", "md"):
            p = _V383_PREREG[k]["path"]
            b = open(p, "rb").read()
            out["sha256"][k] = hashlib.sha256(b).hexdigest()
            out[k] = json.loads(b.decode("utf-8")) if k == "json" else b.decode("utf-8")
    except Exception as e:
        out["erro"] = repr(e)
    return out


def _v383_derive_outcome(core, spec):
    """deriva o desfecho de uma cobranca NUMBER_READ pelo valor lido do core e pela regra dita; devolve (desfecho, valor, controle). Regras: abs_z_lt_5
    (|z| < 5 -> NOT_FALSIFIED); z_gain_ge_plus5_falsifies (UNILATERAL: z_ganho >= +5 -> FALSIFIED); control_then_abs_z_lt_5 (controle != control_ok ->
    INCONCLUSIVE; senao |z| < 5); kill_rule_flag (a regra de morte congelada: o booleano lido -> FALSIFIED sse True). Valor ausente -> AWAITING."""
    v = _v383_get(core, spec["path"]); ctrl = _v383_get(core, spec["control"]) if spec.get("control") else None
    rule = spec["rule"]
    if rule == "kill_rule_flag":
        if not isinstance(v, bool):
            return "AWAITING", v, ctrl
        return ("FALSIFIED" if v else "NOT_FALSIFIED"), v, ctrl
    if isinstance(v, bool) or not isinstance(v, (int, float)):
        return "AWAITING", v, ctrl
    if rule == "abs_z_lt_5":
        return ("NOT_FALSIFIED" if abs(float(v)) < 5.0 else "FALSIFIED"), v, ctrl
    if rule == "z_gain_ge_plus5_falsifies":
        return ("FALSIFIED" if float(v) >= 5.0 else "NOT_FALSIFIED"), v, ctrl
    if rule == "control_then_abs_z_lt_5":
        if ctrl != spec.get("control_ok"):
            return "INCONCLUSIVE", v, ctrl
        return ("NOT_FALSIFIED" if abs(float(v)) < 5.0 else "FALSIFIED"), v, ctrl
    return "AWAITING", v, ctrl


